 check(journey(f,at,-1),"actual later town entrance reaches the real control-room waypoint");auto p=model(f,at);check(p.targets.size()==1&&p.targets[0].goal.entity_id==9,"current-floor local2 initially selects the real operator");check(journey(f,at,9),"native operator is reachable from the real control-room arrival");f.local[2]=1;
 p=model(f,at);check(p.targets.size()==1&&p.targets[0].goal.entity_id==3&&p.finish_on_scenario==434,"native operator receipt selects the actual later lever3,not earlier performance lever6");check(model(f,at,{false,true}).targets.empty(),"Navigation off withholds the physical later puzzle");check(!model(f,at,{true,false}).targets.empty(),"Other guidance is independent of the later navigation puzzle");check(journey(f,at,3),"post-conversation player pose reaches the correct dragon lever");
 f.current_map_id=290;f.scenario[434]=1;check(model(f,entry(290)).finished,"only the actual completed outside434 return finishes the dragon sequence");
 const auto* room=baked::submap_by_map_id(293);const baked::Object* arc=nullptr,*lever=nullptr;for(const auto& o:baked::grids(*room).objects)if(o.entity_id()==3){if(o.type==baked::ObjType::Warp)arc=&o;else if(o.type==baked::ObjType::Entity)lever=&o;}if(!arc||!lever)return 2;const auto landing=entry(290,arc->b);check(arc->a==290&&arc->b<0&&(arc->d&255)==2&&baked::world_exit(*arc),"manual repeat edge has the full final outside destination,not the boss arena");check(landing==Cell{1,26,20},"actual crop40,22 and Ground66,39 plus three South steps yield baked26,20");
 for(int mode=0;mode<3;++mode){auto g=f;g.current_map_id=293;g.local.fill(0);g.local[2]=1;g.scenario[434]=mode==0?std::optional<int>{}:std::optional<int>(mode==2);map_state::Resolver state(g,fixture::records);check(state.consumed(*room,*arc)==(mode!=2),"missing/incomplete434 cannot turn the one-time boss scene into ordinary travel");check(!state.consumed(*room,*lever),"physical lever always remains approachable");auto route=exit_route(g,{1,16,8},landing);check(route.path.success,"normal foot exit remains valid regardless of boss completion");const auto transition=route.pending.incoming_transition;check(mode==2?transition&&transition->map_id==293&&transition->entity_id==3:!transition||transition->map_id!=293||transition->entity_id!=3,"only the completed boss permits the optional manual lever shortcut");if(mode==2)check(transition->arrival==landing&&!route.path.walk_phases.empty()&&route.path.walk_phases.back().manual_after,"repeat route stops for interaction and retains the exact complete landing");}
 f.current_map_id=293;f.scenario[434]=0;f.local.fill(0);f.local[2]=1;at={1,15,8};check(journey(f,at,3),"actual wrong-lever round-trip recovery resumes at the correct lever without repeating the operator");
 for(int map:{291,292,294,295}){f.current_map_id=map;f.local.fill(0);Cell here=entry(map);check(journey(f,here,-1),"each connected later floor can reach the real control-room arrival");}
 f.current_map_id=293;f.scenario[297]=0;check(!model(f,entry(293)).supported,"late guide cannot replace the earlier performance");check(fixture::wrong_owner==0,"all route/model work uses owned data");std::printf("Late Opera:%d assertions/%d failures\n",cases,errors);return errors||fixture::wrong_owner?1:0;
